-- =====================================================================
-- BON Demo V2 — 05: Governed Business Ontology
-- 3 domains, 39 nodes (ENTITY / METRIC / TERM / POLICY_CONCEPT), 49 typed edges.
--
-- Design rules (per internal positioning: "Sense proposes, Ontology governs, SVs execute"):
--   * Every METRIC states the canonical definition in plain language, names the
--     SV metric that implements it, and names the non-canonical variants.
--   * Variants are separate METRIC nodes with a `scope` and a HAS_VARIANT edge.
--   * Code fields are one TERM each, pointing to a reference table; never one node per code value.
--   * Business rules are POLICY_CONCEPT nodes linked with APPLIES_TO.
--   * Cross-domain metrics (margin, profit, break-even, revenue at risk) carry the
--     reasoning chain; the SVs compute each piece.
--
-- Run after 04_enriched_svs.sql. Term references below use Domain.Term paths;
-- if a name collides with a term in another domain, use the termId returned by DRAFT.
-- =====================================================================

-- ---------------------------------------------------------------- Domains
SELECT SYSTEM$CREATE_GLOSSARY_DOMAIN('Procurement', 'Governed procurement concepts: suppliers, materials, purchasing, logistics, bill of materials. Steward: Procurement data steward.');
SELECT SYSTEM$CREATE_GLOSSARY_DOMAIN('Finance & Controlling', 'Governed finance concepts: revenue, COGS, margin, cost allocation, posting rules. Steward: Finance data steward.');
SELECT SYSTEM$CREATE_GLOSSARY_DOMAIN('Sales & Distribution', 'Governed sales concepts: orders, bookings, pricing conditions, discounts, customers. Steward: Sales data steward.');

-- ---------------------------------------------------------------- Procurement nodes
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Supplier","domainName":"Procurement","itemKind":"ENTITY","synonyms":["Vendor","Supply partner"],"description":"A company we buy materials from, recorded in the vendor master (LFA1). Each supplier has an account group (KTOKK) that determines whether it counts as an active supplier."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Material","domainName":"Procurement","itemKind":"ENTITY","synonyms":["Part","Component","Raw material"],"description":"A purchased item in the material master (MARA), identified by MATNR (MAT-*). Materials are grouped by material group (MATKL)."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Assembly","domainName":"Procurement","itemKind":"ENTITY","synonyms":["Finished good","Product","Sellable product"],"description":"A product we build and sell (ASSY-*), made from materials and sub-assemblies defined in the bill of materials. Assemblies are the items on sales orders."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Bill of Materials","domainName":"Procurement","itemKind":"ENTITY","synonyms":["BOM","Product structure"],"description":"The multi-level structure of components and quantities needed to build one unit of an assembly (STPO). Sub-assemblies have their own BOMs, so costs and dependencies must be traced through every level."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Purchase Order","domainName":"Procurement","itemKind":"ENTITY","synonyms":["PO","PO line"],"description":"An order line placed with a supplier for a material (EKPO). Its net value (NETWR) is procurement spend."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Shipment","domainName":"Procurement","itemKind":"ENTITY","synonyms":["Delivery","Inbound shipment"],"description":"An inbound delivery (LIKP) with a planned delivery date (LFDAT), actual goods issue date (WADAT), and status (D delivered, T in transit, X cancelled)."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Carrier","domainName":"Procurement","itemKind":"ENTITY","synonyms":["Forwarding agent","Logistics provider"],"description":"A logistics provider that moves shipments (LFA2). Carriers self-report an on-time ratio (OTRAT), which is not the official on-time measure."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Inspection Lot","domainName":"Procurement","itemKind":"ENTITY","synonyms":["Quality inspection"],"description":"A quality inspection of a material batch (QALS) with a measured defect rate."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Supplier Count","domainName":"Procurement","itemKind":"METRIC","synonyms":["Number of suppliers","Active suppliers","Active supplier count"],"description":"Official supplier count used in all reporting: the number of active suppliers, meaning vendors in account group ZSTR (strategic) or ZSTD (standard). Probationary vendors (ZPRB) are excluded by procurement policy. Canonical implementation: FINANCE_ENRICHED_SV metric vendors.active_supplier_count. The Purchasing view metric vendor_record_count counts all vendor master records and is an operational variant, not the official count.","formula":"COUNT(DISTINCT LIFNR) WHERE KTOKK IN (ZSTR, ZSTD)","exclusions":["KTOKK = ZPRB (probationary)"],"formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.LFA1"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Vendor Record Count","domainName":"Procurement","itemKind":"METRIC","scope":"Procurement operations","synonyms":["Vendor master record count"],"description":"Operational variant of Supplier Count: every vendor record on file, including probationary vendors. Use only for vendor master data maintenance, never as the supplier count. Implemented by PURCHASING_ENRICHED_SV metric vendors.vendor_record_count.","formula":"COUNT(DISTINCT LIFNR)","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.LFA1"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"On-Time Delivery Rate","domainName":"Procurement","itemKind":"METRIC","synonyms":["OTD","On-time delivery","Delivery performance"],"description":"Official on-time delivery rate: percent of delivered shipments (status D) whose actual goods issue date is on or before the planned delivery date. Canonical implementation: PURCHASING_ENRICHED_SV metric shipments.operational_otd_rate. The carrier self-reported ratio (carrier_otd_rate, OTRAT) is not the official measure.","formula":"100 * COUNT(WADAT <= LFDAT) / COUNT(*) WHERE STATU = D","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.LIKP"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Carrier Reported On-Time Rate","domainName":"Procurement","itemKind":"METRIC","scope":"Carrier scorecard","synonyms":["OTRAT","Carrier OTD"],"description":"Variant of On-Time Delivery Rate: average on-time ratio self-reported by carriers. Useful for carrier negotiations only; not the official delivery performance. Implemented by PURCHASING_ENRICHED_SV metric carriers.carrier_otd_rate.","formula":"AVG(OTRAT) * 100","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.LFA2"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"BOM Cost Rollup","domainName":"Procurement","itemKind":"METRIC","synonyms":["Unit cost to build","Cost to make","Material cost per unit","Product cost"],"description":"Official cost to build one unit of an assembly: sum over every purchased component at every BOM level of extended quantity times component standard price. This is the unit cost for all margin, profit, and pricing decisions. The standard price STPRS stored on an assembly is a planning price, not its cost. Canonical implementation: PURCHASING_ENRICHED_SV metric bom.bom_material_cost grouped by bom.assembly_id.","formula":"SUM(extended_qty * component STPRS) over leaf BOM components, per assembly","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.BOM_EXPLOSION"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Procurement Spend","domainName":"Procurement","itemKind":"METRIC","synonyms":["Purchase spend","Spend"],"description":"Total net value of purchase order lines (EKPO NETWR). Canonical implementation: PURCHASING_ENRICHED_SV metric purchase_orders.procurement_spend.","formula":"SUM(NETWR)","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.EKPO"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Vendor Account Group","domainName":"Procurement","itemKind":"TERM","synonyms":["KTOKK","Vendor type"],"description":"Code field KTOKK on the vendor master that classifies suppliers: ZSTR = strategic partner, ZSTD = standard vendor, ZPRB = probationary. The full code list and the EXCLUDE_FROM_ACTIVE_COUNT flag live in reference table T077K; new codes are added there, not here."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Material Group","domainName":"Procurement","itemKind":"TERM","synonyms":["MATKL","Material category"],"description":"Code field MATKL that classifies materials: 043 Electronics, 044 Chemicals, 045 Metals, 046 Packaging, 047 Raw Materials, 048 Assembly. The full code list lives in reference table T023T."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Probationary Vendor Exclusion","domainName":"Procurement","itemKind":"POLICY_CONCEPT","description":"Procurement policy: vendors in a probationary account group (ZPRB, flagged EXCLUDE_FROM_ACTIVE_COUNT in T077K) are not active suppliers. They are excluded from supplier counts and supplier KPIs until promoted."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"BOM Input Protection","domainName":"Procurement","itemKind":"POLICY_CONCEPT","description":"Procurement policy: a material that is a component, at any BOM level, of an assembly we sell is a production input and must not be cut to reduce spend. Only materials that appear in no sold assembly BOM are discretionary spend."}');

-- ---------------------------------------------------------------- Finance & Controlling nodes
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"AP Line Item","domainName":"Finance & Controlling","itemKind":"ENTITY","synonyms":["Accounts payable posting","Vendor invoice line"],"description":"An accounts payable accounting line (BSEG) for a vendor invoice or credit memo, posted to a GL account with a posting key that sets its direction."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Cost Posting","domainName":"Finance & Controlling","itemKind":"ENTITY","synonyms":["Cost allocation","Controlling posting"],"description":"A controlling cost posting (COEP) allocated to a cost object such as a manufacturing cost center."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"COGS Raw Materials","domainName":"Finance & Controlling","itemKind":"METRIC","synonyms":["Cost of goods sold","COGS","Raw material COGS"],"description":"Official cost of goods sold for raw materials: AP postings on GL 0040100000, with vendor invoices (posting key 31) added and credit memos (posting key 34) subtracted. Canonical implementation: FINANCE_ENRICHED_SV metric ap_lines.cogs_raw_materials.","formula":"SUM(DMBTR if BSCHL=31, -DMBTR if BSCHL=34) WHERE HKONT = 0040100000","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.BSEG"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"COGS Freight","domainName":"Finance & Controlling","itemKind":"METRIC","synonyms":["Freight cost of goods sold","Net freight COGS"],"description":"Freight cost of goods sold: AP postings on GL 0040200000, invoices minus credit memos. Canonical implementation: FINANCE_ENRICHED_SV metric ap_lines.cogs_freight.","formula":"SUM(signed DMBTR) WHERE HKONT = 0040200000","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.BSEG"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Cost Center Total","domainName":"Finance & Controlling","itemKind":"METRIC","synonyms":["Allocated cost","Manufacturing cost"],"description":"Total cost posted to a cost object (OBJNR), for example KS-MFG-US for US Manufacturing. Canonical implementation: FINANCE_ENRICHED_SV metric cost_postings.total_posted_cost filtered by cost_object.","formula":"SUM(WRTBTR) WHERE OBJNR = cost object","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.COEP"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Product Gross Margin","domainName":"Finance & Controlling","itemKind":"METRIC","synonyms":["Gross margin","Product margin"],"description":"Gross margin of an assembly: Revenue (net of customer discounts) minus BOM Cost Rollup times units sold. Revenue comes from the Sales view (net_revenue) and unit cost from the Purchasing view (bom_material_cost); query both and combine. Never use the assembly standard price STPRS as cost, and never use gross bookings as revenue.","formula":"Revenue - (BOM Cost Rollup * units sold), per assembly"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Customer Profit","domainName":"Finance & Controlling","itemKind":"METRIC","synonyms":["Customer profitability","Profit contribution"],"description":"Profit contributed by a customer after material costs: Revenue (net of discounts) for that customer minus BOM Cost Rollup times units sold to that customer, summed over the assemblies they bought. Combines Sales (net_revenue and units_sold by customer and product) with Purchasing (bom_material_cost by assembly).","formula":"SUM over products(Revenue - BOM Cost Rollup * units), per customer"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Break-even Discount","domainName":"Finance & Controlling","itemKind":"METRIC","synonyms":["Maximum discount","Discount floor"],"description":"Largest discount off list price (PR00) before the unit price falls below the cost to build: 1 minus BOM Cost Rollup divided by list price. List price comes from the Sales view (list_price); unit cost from the Purchasing view (bom_material_cost).","formula":"1 - BOM Cost Rollup / list price"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Posting Key","domainName":"Finance & Controlling","itemKind":"TERM","synonyms":["BSCHL"],"description":"Code field BSCHL that sets the direction of an AP line: 31 = vendor invoice (adds cost), 34 = vendor credit memo (reduces cost)."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"GL Account","domainName":"Finance & Controlling","itemKind":"TERM","synonyms":["HKONT","General ledger account"],"description":"Code field HKONT: 0040100000 = COGS Raw Materials, 0040200000 = COGS Freight, 0021100000 = Accounts Payable."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Cost Object","domainName":"Finance & Controlling","itemKind":"TERM","synonyms":["OBJNR","Cost center"],"description":"Code field OBJNR: KS-MFG-US = US Manufacturing, KS-MFG-EU = EU Manufacturing, KS-MFG-AP = APAC Manufacturing, KS-LOG = Logistics, KS-QA = Quality Assurance."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Credit Memo Sign Rule","domainName":"Finance & Controlling","itemKind":"POLICY_CONCEPT","description":"Accounting policy: a vendor credit memo (posting key 34) reverses part of a vendor invoice (posting key 31), so it must be subtracted from every cost and COGS total. Summing raw amounts overstates cost."}');

-- ---------------------------------------------------------------- Sales & Distribution nodes
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Sales Order","domainName":"Sales & Distribution","itemKind":"ENTITY","synonyms":["Order","Sales order line"],"description":"A customer order line for an assembly (VBAP). Its value NETWR is the order value before customer discounts."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Customer","domainName":"Sales & Distribution","itemKind":"ENTITY","synonyms":["Account","Client"],"description":"A company that buys our assemblies, identified by KUNNR."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Pricing Condition","domainName":"Sales & Distribution","itemKind":"ENTITY","synonyms":["Price condition"],"description":"A pricing record on a sales order (KONV): list price, customer discount, or surcharge, distinguished by condition type."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Revenue","domainName":"Sales & Distribution","itemKind":"METRIC","synonyms":["Net revenue","Net sales","Sales revenue"],"description":"Official revenue for all reporting, margin, profit, and risk analysis: order value net of customer discounts (condition type K007). Canonical implementation: SALES_ENRICHED_SV derived metric net_revenue. Gross Bookings (order value before discounts, the Sales view metric gross_bookings) is a sales pipeline variant and is not revenue.","formula":"SUM(VBAP.NETWR) - SUM(ABS(KONV.KWERT)) WHERE KSCHL = K007","exclusions":["Freight surcharges (KF00) are not discounts"],"formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.VBAP"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Gross Bookings","domainName":"Sales & Distribution","itemKind":"METRIC","scope":"Sales pipeline","synonyms":["Bookings","Order value"],"description":"Variant of Revenue used by the Sales team for pipeline and quota: total order value before customer discounts. Not official revenue. Implemented by SALES_ENRICHED_SV metric sales_items.gross_bookings.","formula":"SUM(VBAP.NETWR)","formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.VBAP"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Customer Discounts","domainName":"Sales & Distribution","itemKind":"METRIC","synonyms":["Discount leakage","Revenue lost to discounts"],"description":"Value of customer discounts granted: pricing conditions of type K007 only. Freight surcharges (KF00) are not discounts. Canonical implementation: SALES_ENRICHED_SV metric pricing.customer_discounts.","formula":"SUM(ABS(KWERT)) WHERE KSCHL = K007","exclusions":["KSCHL = KF00 (freight surcharge)"],"formulaSource":"DB_ONTOLOGY_CONTROL_PLANE.SAP_BON_V2.KONV"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Revenue at Risk","domainName":"Sales & Distribution","itemKind":"METRIC","synonyms":["Supplier disruption impact","Exposed revenue"],"description":"Revenue (net of discounts) exposed when a supplier cannot deliver: find the materials the supplier provides (Purchasing purchase orders), find every sold assembly whose BOM contains any of those materials at any level (Purchasing bom, which is already fully exploded), then sum Revenue for those assemblies (Sales net_revenue by product).","formula":"SUM(Revenue) for assemblies whose BOM contains a material supplied by the supplier"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Condition Type","domainName":"Sales & Distribution","itemKind":"TERM","synonyms":["KSCHL"],"description":"Code field KSCHL on pricing conditions: PR00 = list price, K007 = customer discount, KF00 = freight surcharge."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name":"Sales Organization","domainName":"Sales & Distribution","itemKind":"TERM","synonyms":["VKORG","Sales org"],"description":"Code field VKORG: 1000 = Americas, 2000 = EMEA, 3000 = APAC."}');

